/**
 * The shop's words that its first page never draws, in both languages: the
 * product page's, the bag's, checkout's, the account's, sign-in's — every word
 * a page the shop fetches later draws, and nothing the first download needs.
 *
 * **Its own module, so the first page does not wait for it.** The first
 * download spelled out about a third of the shop's words; the rest, about
 * 90 KB gzipped, came with it all the same. They arrive now with the first
 * page the shop fetches later: `lazyPage` loads this file beside every page,
 * dialog and drawer it fetches, so none of them is drawn before its words are
 * here (`laterWords`), and the route table preloads it with every page a
 * link can open first (`Frontend/Web/build/routePreloads.ts`). A home page
 * reached first never waits for it; it is fetched while the browser is idle,
 * with the product and department pages.
 *
 * `messagePlacement.test.ts` keeps the line: a key the first download, the
 * shared rules or the server spells out belongs in `dictionary.ts`; one only
 * a later page spells out belongs here; one only the portal does in
 * `portalMessages.ts`. `laterAr` is typed as a complete record of the
 * English keys, the dictionary's own rule.
 */
import { addMessages } from "./dictionary.js";

